import NavbarGooeyBloom from '@/components/tweenui/navbar-gooey-bloom';

export default function Page() {
  return <NavbarGooeyBloom />;
}

'use client';

import { useRouter } from 'next/navigation';
import NavbarGooeyBloom from '@/components/tweenui/navbar-gooey-bloom';

export default function Layout({ children }: { children: React.ReactNode }) {
  const router = useRouter();

  return (
    <NavbarGooeyBloom
      brand="Kairo"
      currentHref="/pricing"
      actionLabel="Start free"
      onActionClick={() => router.push('/signup')}
      menus={[
        {
          label: 'Product',
          columns: [
            [
              {
                label: 'Overview',
                href: '/product',
                description: 'What it does, in one screen.',
                icon: 'bloom',
              },
              {
                label: 'Pricing',
                href: '/pricing',
                description: 'Three plans, no surprises.',
                icon: 'layers',
              },
            ],
          ],
          feature: {
            title: 'What is new',
            description: 'The changelog, kept short.',
            href: '/changelog',
            cta: 'Read it',
          },
        },
        { label: 'Docs', href: '/docs' },
      ]}
    >
      {children}
    </NavbarGooeyBloom>
  );
}
